use async_trait :: async_trait ; use derive_setters :: Setters ; use forge_domain :: { ContextMessage , Conversation , EventData , EventHandle , RequestPayload , Role , TextMessage , ToolCallArguments , ToolName , } ; use forge_template :: Element ; use tracing :: warn ; use crate :: TemplateEngine ; use forge_domain :: { Context , ContextMessage , ConversationId , MessageEntry , ToolCallArguments , ToolCallFull , } ; use pretty_assertions :: assert_eq ; use super :: * ; # [doc = " Implementation of EventHandle for DoomLoopDetector"] # [doc = ""] # [doc = " This allows the detector to run on request events so the previous turn's"] # [doc = " tool calls and results are already appended in context before reminders are"] # [doc = " inserted."] # [async_trait] impl EventHandle < EventData < RequestPayload > > for DoomLoopDetector { async fn handle (& self , event : & EventData < RequestPayload > , conversation : & mut Conversation ,) -> anyhow :: Result < () > { if let Some (consecutive_calls) = self . detect_from_conversation (conversation) { warn ! (agent_id = % event . agent . id , request_count = event . payload . request_count , consecutive_calls , "Doom loop detected from conversation context before next request") ; if let Some (context) = conversation . context . as_mut () { let reminder = TemplateEngine :: default () . render ("forge-doom-loop-reminder.md" , & serde_json :: json ! ({ "consecutive_calls" : consecutive_calls }) ,) ? ; let content = Element :: new ("system_reminder") . cdata (reminder) ; context . messages . push (ContextMessage :: user (content , None) . into ()) ; } } Ok (()) } }